<?php namespace App\Http\Controllers\API; use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Password; use Illuminate\Support\Str; class PasswordResetController extends Controller { public function requestLink(Request $request){$data=$request->validate(["email"=>["required","email"]]);Password::sendResetLink(["email"=>$data["email"]]);return response()->json(["message"=>"If that email belongs to an account, a reset link has been sent."]);} public function reset(Request $request){$data=$request->validate(["token"=>["required","string"],"email"=>["required","email"],"password"=>["required","string","min:8","confirmed"]]);$status=Password::reset($data,function($user,$password){$user->forceFill(["password"=>Hash::make($password),"remember_token"=>Str::random(60)])->save();});return $status===Password::PASSWORD_RESET?response()->json(["message"=>"Password updated. You can now sign in."]):response()->json(["message"=>__($status),"errors"=>["email"=>[__($status)]]],422);} }